<style id="cheops-service-motion-css">
  /* fast cinematic page entrance */
  #motionIntro{position:fixed;inset:0;z-index:9998;background:#111;display:grid;place-items:center;pointer-events:none;transition:opacity .8s cubic-bezier(.76,0,.24,1),visibility .8s ease}
  #motionIntro.done{opacity:0;visibility:hidden}
  #motionIntro .mi-inner{width:min(520px,72vw);text-align:center;color:#fff}
  #motionIntro .mi-word{font-family:"Romie",Georgia,serif;font-size:clamp(1.35rem,3.6vw,3.06rem);letter-spacing:-.02em;opacity:0;transform:translateY(18px);animation:miWord .7s .08s cubic-bezier(.16,1,.3,1) forwards}
  #motionIntro .mi-line{height:1px;background:rgba(255,255,255,.16);overflow:hidden;margin-top:18px}
  #motionIntro .mi-line i{display:block;width:100%;height:100%;background:#d8c49a;transform:scaleX(0);transform-origin:left;animation:miLine .85s .12s cubic-bezier(.16,1,.3,1) forwards}
  @keyframes miWord{to{opacity:1;transform:none}}
  @keyframes miLine{to{transform:scaleX(1)}}

  #motionProgress{position:fixed;left:0;top:0;height:2px;width:0;z-index:9999;background:#d8c49a;pointer-events:none;box-shadow:0 0 14px rgba(216,196,154,.3)}

  /* hero choreography */
  .hero{isolation:isolate}
  .hero::after{content:"";position:absolute;inset:0;z-index:1;pointer-events:none;background:radial-gradient(circle at 72% 38%,rgba(216,196,154,.14),transparent 34%);opacity:.1;transition:opacity 1.2s ease}
  .motion-loaded .hero::after{opacity:1}
  .hero-bg{will-change:transform;transition:transform 1.8s cubic-bezier(.16,1,.3,1),filter 1.5s ease!important}
  .motion-ready .hero-bg{transform:scale(1.095)!important;filter:saturate(.62) brightness(.82)!important}
  .motion-ready.motion-loaded .hero-bg{transform:scale(1.025)!important;filter:saturate(.78) brightness(1)!important}
  .hero-content{position:relative;z-index:2}
  .motion-ready .hero-content>.eyebrow,
  .motion-ready .hero-content>h1,
  .motion-ready .hero-content>.lead,
  .motion-ready .hero-content>.hero-actions{opacity:0;transform:translateY(42px);filter:blur(7px)}
  .motion-ready.motion-loaded .hero-content>.eyebrow{animation:heroRise .85s .13s cubic-bezier(.16,1,.3,1) forwards}
  .motion-ready.motion-loaded .hero-content>h1{animation:heroRise 1.05s .22s cubic-bezier(.16,1,.3,1) forwards}
  .motion-ready.motion-loaded .hero-content>.lead{animation:heroRise .95s .36s cubic-bezier(.16,1,.3,1) forwards}
  .motion-ready.motion-loaded .hero-content>.hero-actions{animation:heroRise .9s .47s cubic-bezier(.16,1,.3,1) forwards}
  @keyframes heroRise{to{opacity:1;transform:none;filter:blur(0)}}

  /* deeper reveal than the original simple fade */
  .reveal{opacity:0!important;transform:translateY(54px) scale(.982)!important;filter:blur(7px);transition:opacity .95s cubic-bezier(.16,1,.3,1),transform .95s cubic-bezier(.16,1,.3,1),filter .9s ease!important;will-change:transform,opacity,filter}
  .reveal.on{opacity:1!important;transform:none!important;filter:blur(0)!important}

  /* cards / rows */
  .service-card,.pillar,.next-card,.handle,.step{will-change:transform}
  .service-card{transform-style:preserve-3d;transition:border-color .45s ease,box-shadow .6s cubic-bezier(.16,1,.3,1),background .45s ease!important}
  .service-card::before{content:"";position:absolute;inset:-1px;pointer-events:none;background:radial-gradient(420px circle at var(--mx,50%) var(--my,50%),rgba(216,196,154,.15),transparent 45%);opacity:0;transition:opacity .35s ease;z-index:0}
  .service-card:hover::before{opacity:1}
  .service-card>*{position:relative;z-index:1}
  .service-card:hover{box-shadow:0 35px 75px -48px rgba(0,0,0,.42);border-color:rgba(180,151,93,.38)!important}
  .service-card .arrow,.next-card .arrow{transition:transform .45s cubic-bezier(.16,1,.3,1)!important}
  .service-card:hover .arrow,.next-card:hover .arrow{transform:translate(5px,-5px)}
  .svc-icon{transition:transform .55s cubic-bezier(.16,1,.3,1),background .4s ease}
  .service-card:hover .svc-icon{transform:rotate(-5deg) scale(1.08)}

  .pillar{transition:transform .55s cubic-bezier(.16,1,.3,1),box-shadow .55s ease,border-color .4s ease!important}
  .pillar:hover{transform:translateY(-7px);box-shadow:0 30px 70px -50px rgba(0,0,0,.45);border-color:rgba(180,151,93,.35)!important}
  .handle{position:relative;overflow:hidden}
  .handle::after{content:"";position:absolute;left:0;bottom:-1px;width:100%;height:1px;background:#d8c49a;transform:scaleX(0);transform-origin:left;transition:transform .75s cubic-bezier(.16,1,.3,1)}
  .handle.on::after{transform:scaleX(1)}
  .handle span:first-child,.handle svg{transition:transform .5s cubic-bezier(.16,1,.3,1)}
  .handle:hover span:first-child,.handle:hover svg{transform:translateX(6px)}

  .step .n{display:inline-block;transition:transform .5s cubic-bezier(.16,1,.3,1),color .35s ease}
  .step:hover .n{transform:translateY(-5px);color:#d8c49a}

  /* magnetic buttons visual polish */
  .btn{will-change:transform;transition:background .35s ease,color .35s ease,border-color .35s ease,box-shadow .35s ease!important}
  .btn:hover{box-shadow:0 18px 40px -28px rgba(0,0,0,.5)}

  /* moving CTA sheen */
  .cta{position:relative;isolation:isolate}
  .cta::before{content:"";position:absolute;inset:-35%;z-index:-1;pointer-events:none;background:radial-gradient(circle,rgba(216,196,154,.18),transparent 34%);animation:ctaDrift 11s ease-in-out infinite alternate}
  @keyframes ctaDrift{from{transform:translate3d(-8%,-4%,0) scale(.92)}to{transform:translate3d(13%,8%,0) scale(1.08)}}

  /* custom cursor */
  #motionCursor{position:fixed;left:0;top:0;width:13px;height:13px;border-radius:50%;background:#d8c49a;z-index:9997;pointer-events:none;opacity:0;transform:translate(-50%,-50%);transition:width .3s cubic-bezier(.16,1,.3,1),height .3s cubic-bezier(.16,1,.3,1),opacity .2s ease,background .3s ease;mix-blend-mode:difference}
  #motionCursor.big{width:78px;height:78px;mix-blend-mode:normal;background:rgba(216,196,154,.94)}
  #motionCursor b{position:absolute;inset:0;display:grid;place-items:center;font-size:.432rem;letter-spacing:.15em;text-transform:uppercase;color:#111;opacity:0;transition:opacity .2s;white-space:nowrap}
  #motionCursor.big b{opacity:1}

  /* service dropdown gets an actual entrance */
  .service-menu{transform-origin:top center;transition:opacity .28s ease,transform .38s cubic-bezier(.16,1,.3,1),visibility .28s ease!important;transform:translateY(10px) scale(.97)}
  .service-nav.open .service-menu{transform:translateY(0) scale(1)}
  .service-menu a{transition:transform .28s ease,background .28s ease!important}
  .service-menu a:hover{transform:translateX(5px)}

  @media(max-width:1023px){#motionCursor{display:none}.service-card:hover,.pillar:hover{transform:none}}
  @media(prefers-reduced-motion:reduce){
    #motionIntro{display:none!important}#motionProgress{display:none}.hero-bg,.reveal,.hero-content>*{animation:none!important;transition:none!important;transform:none!important;filter:none!important;opacity:1!important}.cta::before{animation:none!important}#motionCursor{display:none!important}
  }
</style>
<style id="home-about-parity">
/* =========================================================
   CHEOPS PRIVÉ — HOME / ABOUT MOTION + UI PARITY
