.btn::before{content:"";position:absolute;inset:0;z-index:-1;border-radius:inherit;background:linear-gradient(120deg,var(--gold,#e5cfa7) 0%,#f6e7c8 30%,var(--violet) 70%,var(--teal) 100%);background-size:260% 260%;transform:translateY(102%);transition:transform .6s cubic-bezier(.16,1,.3,1)}
.btn:hover::before{transform:translateY(0);animation:btnShift 3.2s linear infinite}
.btn:hover{color:#111!important;border-color:transparent!important;transform:translateY(-3px);box-shadow:0 18px 40px -18px rgba(109,91,208,.55)}
.btn .ar{display:inline-block;transition:transform .5s}
