.hero .btn-ghost:hover,.hero .btn.ghost:hover{color:#111!important}
@keyframes btnShift{0%{background-position:0% 50%}100%{background-position:200% 50%}}

/* HOME/ABOUT nav pill */
.nav{background:transparent!important;border:0!important;padding:0!important;transition:background .6s,border-color .6s,backdrop-filter .6s!important}
.nav .nav-inner{margin-top:10px!important;border-radius:999px!important;padding:12px 22px!important;transition:background .6s,box-shadow .6s,color .6s!important}
.nav.scrolled{background:transparent!important;backdrop-filter:none!important;border-bottom-color:transparent!important}
.nav.scrolled .nav-inner{background:rgba(255,255,255,.82)!important;backdrop-filter:blur(16px)!important;box-shadow:0 18px 40px -30px rgba(0,0,0,.5)!important;color:var(--ink,#1a1a1a)!important}
.nav.scrolled .logo{filter:none!important}
.nav-link,.service-trigger{position:relative}
.nav-link::after,.service-trigger::after{content:"";position:absolute;left:0;bottom:-5px;height:1px;width:0;background:var(--gold,#e5cfa7);transition:width .5s}
.nav-link:hover::after,.service-trigger:hover::after{width:100%}
.nav-cta{border-radius:999px!important;transition:transform .4s cubic-bezier(.16,1,.3,1),background .35s,color .35s!important}
.nav-cta:hover{transform:translateY(-2px)}
.service-menu{transform:translateY(12px) scale(.985)!important;opacity:0!important;visibility:hidden!important;pointer-events:none!important;transition:opacity .45s cubic-bezier(.16,1,.3,1),transform .45s cubic-bezier(.16,1,.3,1),visibility .45s!important}
.service-nav.open .service-menu{transform:none!important;opacity:1!important;visibility:visible!important;pointer-events:auto!important}
.service-menu a{transform:translateX(-6px);opacity:.72;transition:transform .35s cubic-bezier(.16,1,.3,1),opacity .35s,color .35s}
.service-menu a:hover{transform:none;opacity:1;color:var(--gold2)}

/* hero exactly uses the same deep cinematic motion grammar */
.hero{min-height:78svh!important;align-items:flex-end!important;overflow:hidden!important;background:#000!important}
.hero-bg,#heroImg{will-change:transform;transform:scale(1.04);border-radius:0!important}
.hero-content{padding-bottom:58px!important;position:relative;z-index:3}
.hero .eyebrow{opacity:.82}
.hero .lead{max-width:700px}
.hero-scroll{position:absolute;right:clamp(20px,4vw,58px);bottom:50px;z-index:4;display:flex;align-items:center;gap:14px;color:#fff}
.scroll-line{display:inline-block;width:1px;height:52px;background:linear-gradient(var(--gold,#e5cfa7),transparent);animation:sl 2.4s infinite}
@keyframes sl{0%{transform:scaleY(.2);transform-origin:top}50%{transform:scaleY(1);transform-origin:top}100%{transform:scaleY(.2);transform-origin:bottom}}

/* same image treatment */
.zoom{overflow:hidden}
.zoom img,.editorial-image img,.image-panel img{transition:transform 1.6s cubic-bezier(.16,1,.3,1)}
.zoom:hover img,.editorial-image:hover img,.image-panel:hover img{transform:scale(1.07)}

/* boxed architectural panes like the current Home/About */
main{overflow:visible!important}
main>section:not(.hero){width:min(1680px,calc(100% - 40px))!important;max-width:1680px!important;margin:0 auto 24px!important;border-radius:32px!important;overflow:hidden!important;position:relative}
main>section.hero{width:100%!important;max-width:none!important;margin:0 0 24px!important;border-radius:0!important}
.section.paper{background:linear-gradient(180deg,#faf8f5,#f2eee8)!important}
.section{position:relative}

/* cards use the Home property/project physicality */
.service-card,.pillar,.handle,.next-card{border-radius:28px!important;transition:transform .65s cubic-bezier(.16,1,.3,1),box-shadow .65s,border-color .45s,background .45s!important;transform-style:preserve-3d}
.service-card:hover,.pillar:hover,.handle:hover,.next-card:hover{box-shadow:0 40px 90px -45px rgba(109,91,208,.28)!important;border-color:rgba(201,168,106,.45)!important}
.service-card .arrow,.next-card .arrow{display:inline-block;transition:transform .5s}
.service-card:hover .arrow,.next-card:hover .arrow{transform:translate(7px,-4px)}
.eyebrow.gold{display:inline-flex;align-items:center;gap:8px;padding:8px 16px;border-radius:999px;background:linear-gradient(120deg,rgba(229,207,167,.35),rgba(255,255,255,.16));color:#8a6b2f}

/* marquee from Home */
.marq{overflow:hidden;border-top:1px solid var(--line,rgba(26,26,26,.12));padding:18px 0!important;margin:0 auto 24px!important;border-radius:999px!important;width:min(1680px,calc(100% - 40px))!important;background:rgba(255,255,255,.62);backdrop-filter:blur(12px)}
.marq>div{display:flex;gap:56px;width:max-content;animation:marq 26s linear infinite}
.marq span{font-family:"Romie",serif;font-size:1.35rem;white-space:nowrap}
@keyframes marq{to{transform:translateX(-50%)}}

/* Home cursor + progress */
.cursor{position:fixed;top:0;left:0;z-index:9999;width:14px;height:14px;border-radius:50%;background:var(--gold,#e5cfa7);pointer-events:none;mix-blend-mode:difference;transition:width .35s,height .35s,opacity .35s;display:grid;place-items:center;opacity:0}
.cursor.big{width:96px;height:96px;background:rgba(229,207,167,.92);mix-blend-mode:normal}
.cursor b{font-size:.45rem;letter-spacing:.16em;text-transform:uppercase;color:#1a1a1a;opacity:0;white-space:nowrap}
.cursor.big b{opacity:1}
#prog{position:fixed;top:0;left:0;height:3px;width:0;z-index:10000;background:linear-gradient(90deg,var(--gold,#e5cfa7),#fff,var(--gold2))}

/* exact Home numeric preloader */
#pre{position:fixed;inset:0;z-index:2147483647;background:var(--ink,#1a1a1a);color:#f4f1ec;display:grid;place-items:center;transition:clip-path 1.2s cubic-bezier(.76,0,.24,1),opacity .6s;clip-path:inset(0 0 0 0)}
#pre.done{clip-path:inset(0 0 100% 0);pointer-events:none}
#pre .cnt{font-family:"Romie",serif;font-size:clamp(3.6rem,12.6vw,9rem);line-height:1;margin-top:22px}
#pre .bar{width:min(320px,60vw);height:1px;background:rgba(255,255,255,.18);margin:26px auto 0;overflow:hidden}
#pre .bar i{display:block;height:100%;width:0;background:var(--gold,#e5cfa7)}

/* soft section glow, same idea as Home */
.blob{position:absolute;border-radius:50%;filter:blur(70px);pointer-events:none;z-index:0}
.section>.wrap,.quote-band>.wrap,.cta>.wrap{position:relative;z-index:1}
.rule-gold{height:1px;background:var(--gold,#e5cfa7)}

/* mobile menu choreography */
.mobile-menu.open a{opacity:0;transform:translateY(28px);animation:mi .7s cubic-bezier(.16,1,.3,1) forwards}
@keyframes mi{to{opacity:1;transform:none}}

@media(max-width:1023px){.cursor{display:none}.hero-scroll{display:none}}
@media(max-width:768px){
 main>section:not(.hero),.marq{width:calc(100% - 20px)!important;border-radius:20px!important;margin-bottom:14px!important}
 main>section.hero{width:100%!important;border-radius:0!important;margin-bottom:14px!important}
 .hero{min-height:72svh!important}.hero-content{padding-bottom:40px!important}
}
@media(prefers-reduced-motion:reduce){
 .reveal,.rl>span{transition:none!important;opacity:1!important;transform:none!important}
 .marq>div,.scroll-line,.btn:hover::before{animation:none!important}
}
